        {/* Back Side */}
        <div
          className="absolute inset-0 backface-hidden glass-panel flex flex-col items-center justify-center p-8 bg-brand border border-white/20 text-black rotate-y-180"
          style={{ transform: 'rotateY(180deg)' }}
